import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage facet test.'});
const createSession = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'use tool', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

describe('afterModelResponse usage aggregation', () => {
  it('receives the sum of usage from all rounds', async () => {
    let reportedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'd', inputSchema: {}}, async () => 'r');

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15})],
        [{type: 'text', text: 'done'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30})],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(createSession());

    // Currently it only returns the last one: {inputTokens: 20, outputTokens: 10, totalTokens: 30}
    // We want the sum: {inputTokens: 30, outputTokens: 15, totalTokens: 45}
    expect(reportedUsage).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
  });
});

