export function sumUsage(base?: UsageMetadata, round?: UsageMetadata): UsageMetadata | undefined {
  if (!round) return base;
  if (!base) return round;

  return {
    inputTokens: base.inputTokens + round.inputTokens,
    outputTokens: base.outputTokens + round.outputTokens,
    totalTokens: base.totalTokens + round.totalTokens,
  };
}

